    'Automatique (conseillé)': ['Automatic (recommended)', 'تلقائي (موصى به)', '自动（推荐）'],
    'Rapide · small (0,5 Go)': ['Fast · small (0.5 GB)', 'سريع · small (0.5 غيغابايت)', '快速 · small（0.5 GB）'],
    'Équilibré · medium (1,5 Go)': ['Balanced · medium (1.5 GB)', 'متوازن · medium (1.5 غيغابايت)', '均衡 · medium（1.5 GB）'],
    'Précis · large-v3-turbo (1,6 Go)': ['Accurate · large-v3-turbo (1.6 GB)', 'دقيق · large-v3-turbo (1.6 غيغابايت)', '精准 · large-v3-turbo（1.6 GB）'],
    'Maximum · large-v3 (3 Go)': ['Maximum · large-v3 (3 GB)', 'أقصى دقة · large-v3 (3 غيغابايت)', '最高 · large-v3（3 GB）'],
