    'Démarrer la dictée (mains libres)': ['Start dictation (hands-free)', 'بدء الإملاء (دون استخدام اليدين)', '开始听写（免手持）'],
    'Ouvrir le déroulé ({keys})': ['Open the panel ({keys})', 'فتح اللوحة ({keys})', '打开面板（{keys}）'],
    'Arrêter la réunion': ['Stop the meeting', 'إيقاف الاجتماع', '停止会议'],
    'Enregistrer une réunion': ['Record a meeting', 'تسجيل اجتماع', '录制会议'],
    ' (indisponible)': [' (unavailable)', ' (غير متاح)', '（不可用）'],
    'Moteur : {engine}': ['Engine: {engine}', 'المحرك: {engine}', '引擎：{engine}'],
    'Quitter': ['Quit', 'إنهاء', '退出'],
    'Téléchargement…': ['Downloading…', 'جارٍ التنزيل…', '正在下载…'],
    'Téléchargement du modèle · {size} Go': ['Downloading the model · {size} GB', 'جارٍ تنزيل النموذج · {size} غيغابايت', '正在下载模型 · {size} GB'],
    'Téléchargement · {pct} %': ['Downloading · {pct}%', 'جارٍ التنزيل · {pct}%', '正在下载 · {pct}%'],
    'Téléchargement du modèle · {pct} % ({done} / {total} Go)': ['Downloading the model · {pct}% ({done} / {total} GB)', 'جارٍ تنزيل النموذج · {pct}% ({done} / {total} غيغابايت)', '正在下载模型 · {pct}%（{done} / {total} GB）'],
    'Modèle en téléchargement{progress}': ['Model downloading{progress}', 'النموذج قيد التنزيل{progress}', '模型下载中{progress}'],
